-- Korean locale additions for `quest_offer_reward_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_quest_offer_reward_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_quest_offer_reward_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `RewardText` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;

















UPDATE `quest_offer_reward_locale` AS `l`
INNER JOIN `_koKR_stage_quest_offer_reward_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
INNER JOIN `quest_offer_reward` AS `p` ON `p`.`ID` = `s`.`ID`
SET `l`.`RewardText` = IF(`s`.`RewardText` IS NOT NULL AND (`l`.`RewardText` IS NULL OR `l`.`RewardText` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`RewardText`, `l`.`RewardText`);

SELECT `s`.`ID`, 'koKR', `s`.`RewardText`
FROM `_koKR_stage_quest_offer_reward_locale` AS `s`
INNER JOIN `quest_offer_reward` AS `p` ON `p`.`ID` = `s`.`ID`
LEFT JOIN `quest_offer_reward_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_quest_offer_reward_locale`;
